mapper.select:
SELECT m.id, m.conversation_id AS conversationId, m.sender_id AS senderId, u.nickname AS senderNickname, m.content, m.type, m.client_msg_id AS clientMsgId, m.created_at AS createdAt FROM message m INNER JOIN sys_user u ON u.id = m.sender_id WHERE m.conversation_id = #{conversationId}
AND m.id < #{beforeId}
ORDER BY m.id DESC LIMIT #{limit}
